#!/usr/bin/env python3
"""
Chinna V5 - one-file installer.
Run:  python3 chinna_v5.py
Re-run any time for a clean reinstall. No heredocs, no shell-paste issues.
"""
import base64, os, subprocess, time, sys

HOME = os.path.expanduser('~')
CHINNA = os.path.join(HOME, '.chinna')
DASH = os.path.join(CHINNA, 'dashboard')
PORT = 7777

SERVER_B64 = ""
DASH_B64 = ""

def main():
    print("\n  CHINNA V5 installer\n  " + "-"*30)
    print("  Stopping any old server...")
    os.system("pkill -9 -f dashboard_server 2>/dev/null")
    os.system("pkill -9 -f 'server.py 7777' 2>/dev/null")
    time.sleep(2)

    os.makedirs(DASH, exist_ok=True)

    print("  Writing server...")
    with open(os.path.join(CHINNA, 'dashboard_server.py'), 'wb') as f:
        f.write(base64.b64decode(SERVER_B64))
    print("  Writing dashboard...")
    with open(os.path.join(DASH, 'index.html'), 'wb') as f:
        f.write(base64.b64decode(DASH_B64))

    print("  Starting server on port %d..." % PORT)
    subprocess.Popen(['python3', os.path.join(CHINNA, 'dashboard_server.py'), str(PORT)],
                     stdout=open(os.path.join(CHINNA, 'dashboard.log'), 'w'),
                     stderr=subprocess.STDOUT, start_new_session=True)
    time.sleep(3)

    try:
        import urllib.request, json
        d = json.loads(urllib.request.urlopen('http://localhost:%d/api/stats' % PORT, timeout=5).read())
        print("  Health: CPU %s%% | RAM %s%% | DISK %s%%" % (
            d.get('cpu',{}).get('pct','?'), d.get('memory',{}).get('pct','?'), d.get('disk',{}).get('pct','?')))
    except Exception as e:
        print("  (server still warming up: %s)" % e)

    print("\n  " + "="*30)
    print("  CHINNA V5 READY  ->  http://localhost:%d" % PORT)
    print("  " + "="*30 + "\n")
    os.system("open http://localhost:%d 2>/dev/null" % PORT)

if __name__ == '__main__':
    main()
